            pr_open: false,
        },
        _ => return None,
    })
}

/// Runs the named scenario (`red`, `green`, `merged`) on the first live mission.
#[tauri::command(rename_all = "snake_case")]
pub async fn e2e_gate_poll(app: AppHandle, scenario_name: String) -> Result<String, String> {
