        .ok_or("no live mission")?;
    let shell = app.state::<Shell>();
    let template = shell.template.clone();
    let now = Timestamp::now();
    let events = scenario
        .kinds
        .into_iter()
        .enumerate()
        .map(|(index, (kind, role))| Event {
            id: EventId(format!("e2e-gate-{scenario_name}-{index}")),
            mission_id: mission.clone(),
            milestone_id: Some(MilestoneId(MILESTONE.to_owned())),
            feature_id: None,
            lane: template.lane_of(&kind, role),
            overlay: None,
            kind,
            role,
            session_id: None,
            model: None,
            at: Timestamp(now.0 + time::Duration::milliseconds(index as i64)),
            duration: None,
            usage: None,
            source: SourcePtr::GitHub {
                url: PR_URL.to_owned(),
            },
            mapping_version: MappingVersion::LATEST,
        })
        .collect();
    let poll = Poll {
        observed_at: now,
        pr: None,
        checks: Vec::new(),
        reviews: Vec::new(),
        attestations: Vec::new(),
        gate: Some(GateFacts {
            policy: MergePolicy {
                requires_human: true,
                allowed_methods: vec![MergeMethod::Squash],
                decided_by: RuleAttribution::Ruleset {
                    id: RULESET_ID,
                    name: RULESET_NAME.to_owned(),
                },
                required_checks: vec![REQUIRED_CHECK.to_owned()],
            },
            required_checks: vec![RequiredCheck {
                name: REQUIRED_CHECK.to_owned(),
                conclusion: scenario.conclusion,
            }],
            reviews: 0,
            attestation_ids: Vec::new(),
            pr_open: scenario.pr_open,
        }),
        events,
        windows: Vec::new(),
    };
    let mut store = shell
        .store
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let mut shown = None;
    crate::github::apply_poll(&app, &mut store, &MissionId(mission.0.clone()), poll, &mut shown);
    Ok(mission.to_string())
}
